function @beacon1_radar($screen:screen,$formattedtext:text, $alt1:number, $zoom:number)
	$screen.draw(0, 0, color(0,0,0,6), $screen.width, $screen.height)
	; Read values
	var $distance1 = input_number("beacon", 1)
	var $adjustedDistance1 = $distance1
	var $_1x = input_number("beacon", 2)
	var $_1y = input_number("beacon", 3)
	var $_1z = input_number("beacon", 4)

	;Create adjusted distance to ensure indicators stay within the UI
	$adjustedDistance1 = $distance1 * (($screen.height/2.01)/$zoom)
	if $distance1 > 80500
		$adjustedDistance1=200

	$screen.draw_circle($screen.width/2 + $_1x * $adjustedDistance1, $screen.height/2 + $_1z * $adjustedDistance1, 4, color(0,0,255, 128),color(0,0,255, 16))
	var $_1x3 = ($screen.width/2 + $_1x * $adjustedDistance1)
	var $_1y3 = ($screen.height/2 + $_1z * $adjustedDistance1)
	$screen.write($_1x3-8, $_1y3-14, gray, text("{}", $formattedText)
	$screen.write($_1x3-8, $_1y3+4, gray, text("dist:{}m", round($distance1))

